const inputItems = $input.all();
const now = new Date().toISOString();

function cleanText(value) {
  return String(value || "")
    .replace(/\s+/g, " ")
    .trim();
}

function ensureArray(value) {
  return Array.isArray(value) ? value : [];
}

function firstNumber(values, fallback) {
  for (const value of values) {
    const n = Number(value);
    if (Number.isFinite(n) && n > 0) return n;
  }
  return fallback;
}

function hasRealLinkedIn(row) {
  const url = cleanText(row.linkedin_url || row.source_url);
  const name = cleanText(row.contact_name);

  return (
    name &&
    !name.startsWith("Manual Search Target") &&
    /^https?:\/\/(www\.)?linkedin\.com\/in\//i.test(url)
  );
}

function isManualPlaceholder(row) {
  const name = cleanText(row.contact_name);
  const linkedin = cleanText(row.linkedin_url);
  const source = cleanText(row.source_url);

  return (
    name.startsWith("Manual Search Target") ||
    linkedin.includes('"') ||
    source.includes('"') ||
    linkedin.toLowerCase().includes("manual search") ||
    source.toLowerCase().includes("linkedin search") ||
    source.toLowerCase().includes("talent acquisition") ||
    source.toLowerCase().includes("hr operations")
  );
}

function contactKey(row) {
  return [
    cleanText(row.job_hash),
    cleanText(row.company).toLowerCase(),
    cleanText(row.contact_name).toLowerCase(),
    cleanText(row.linkedin_url || row.source_url).toLowerCase()
  ].join("|");
}

function dedupeContacts(rows) {
  const map = new Map();

  ensureArray(rows).forEach(row => {
    const key = contactKey(row);
    if (!key || key.replace(/\|/g, "").trim() === "") return;

    const existing = map.get(key);

    if (!existing) {
      map.set(key, row);
      return;
    }

    const currentScore = Number(row.relevance_score || 0);
    const existingScore = Number(existing.relevance_score || 0);

    if (currentScore > existingScore) {
      map.set(key, row);
    }
  });

  return Array.from(map.values()).sort((a, b) => {
    return Number(b.relevance_score || 0) - Number(a.relevance_score || 0);
  });
}

function jobKey(row) {
  return [
    cleanText(row.job_hash),
    cleanText(row.company).toLowerCase(),
    cleanText(row.title).toLowerCase()
  ].join("|");
}

function dedupeJobs(rows) {
  const map = new Map();

  ensureArray(rows).forEach(row => {
    const key = jobKey(row);
    if (!key || key.replace(/\|/g, "").trim() === "") return;
    if (!map.has(key)) map.set(key, row);
  });

  return Array.from(map.values());
}

function getBestBaseItem(items) {
  let best = items[items.length - 1]?.json || {};

  for (const i of items) {
    const j = i.json || {};
    if (j.config && (j.jobs || j.raw_jobs || j.normalized_jobs || j.sheet_rows)) {
      best = j;
    }
  }

  return best;
}

