    sourceItem.apply_package?.sheet_rows?.Tailored_Resumes?.[0]?.final_resume_fields,
    sourceItem.apply_package?.sheet_rows?.Tailored_Resumes?.[0]?.resume_fields,
    sourceItem.apply_package?.sheet_rows?.Tailored_Resumes?.[0]?.resume_template_fields,
    sourceItem.apply_package?.sheet_rows?.Tailored_Resumes?.[0]?.template_fields,
    sourceItem.apply_package?.sheet_rows?.Tailored_Resumes?.[0]?.placeholder_values,
    sourceItem.apply_package?.sheet_rows?.Tailored_Resumes?.[0]?.fields,
    sourceItem.apply_package?.sheet_rows?.Tailored_Resumes?.[0],
    sourceItem.resume_fact_bank?.target_resume_fields,
    sourceItem.resume_fact_bank?.verified_resume_fields,
    sourceItem.resume_fact_bank?.base_resume_fields
  ];
}

function mergeCanonicalFields(sources) {
  const fields = {};

  for (const key of CANONICAL_FIELDS) {
    fields[key] = "";
  }

  for (const source of sources) {
    const objectValue = asObject(source);

    for (const key of CANONICAL_FIELDS) {
      if (cleanText(fields[key])) continue;

      const candidate = cleanText(objectValue[key]);

      if (candidate) {
        fields[key] = candidate;
      }
    }
  }

  return fields;
}

function pickAuthoritativeFields(sourceItem) {
  return mergeCanonicalFields(
    collectFieldSources(sourceItem)
  );
}

function assignFieldAliases(target, fields) {
  const exact = stableFields(fields);

  target.authoritative_resume_fields = deepClone(exact);
  target.final_resume_fields = deepClone(exact);
  target.resume_fields = deepClone(exact);
  target.resume_template_fields = deepClone(exact);
  target.template_fields = deepClone(exact);
  target.doc_fields = deepClone(exact);
  target.google_doc_fields = deepClone(exact);
  target.replacements = deepClone(exact);
  target.fields = deepClone(exact);
  target.authoritative_resume_hash = hashFields(exact);
  target.authoritative_resume_field_chars = totalChars(exact);
  target.authoritative_resume_field_count = CANONICAL_FIELDS.length;
  target.authoritative_resume_populated_field_count =
    populatedFieldCount(exact);

  return exact;
}

function sentenceLooksComplete(value, key = "") {
  const text = cleanText(value);

  if (!text) {
    return OPTIONAL_FIELDS.has(key);
  }

  if (!NARRATIVE_FIELDS.has(key)) {
    return true;
  }

  if (
    /\b(?:and|or|with|to|of|in|using)\s+\d[\d,.%+]*\.?$/i
      .test(text)
  ) {
    return false;
  }

  if (
    /\b(?:and|or|with|to|of|in|using)\.?$/i
      .test(text)
  ) {
    return false;
  }

  if (
    /\b\d[\d,]*\.?$/.test(text) &&
    !/[+%]$/.test(text)
  ) {
    return false;
  }

  const words = text.split(/\s+/).filter(Boolean);

  if (key === "SUMMARY") {
    return words.length >= 24;
  }

  return words.length >= 10;
}

function numericIntegrity(value, approvedNumbers) {
  return numericTokens(value).every(
    (token) => approvedNumbers.has(token)
  );
}

function dedupeList(value) {
  return unique(
    cleanText(value)
      .split(/\s*(?:,|;|\|)\s*/)
      .map(cleanText)
      .filter(Boolean)
  ).join(", ");
}

function jobText(sourceItem) {
  return cleanText([
    sourceItem.full_job_description,
    sourceItem.job_description,
    sourceItem.description_raw,
    sourceItem.manual_job_text,
    sourceItem.description,
    sourceItem.job?.description,
    sourceItem.scored_jobs?.[0]?.description,
    sourceItem.resume_candidates?.[0]?.description,
    sourceItem.title,
    sourceItem.job_title,
    sourceItem.company
  ].filter(Boolean).join(" "));
}

function jobTitle(sourceItem) {
  return cleanText(
    sourceItem.title ||
    sourceItem.job_title ||
    sourceItem.scored_jobs?.[0]?.title ||
    sourceItem.resume_candidates?.[0]?.title ||
    ""
  );
}

function detectRoleProfile(sourceItem) {
  const title = jobTitle(sourceItem).toLowerCase();
  const description = jobText(sourceItem).toLowerCase();

  const exactTitleRules = [
    ["people_analytics", [
      "people analytics", "workforce analytics", "people data"
    ]],
    ["total_rewards", [
      "total rewards", "compensation", "benefits", "payroll"
    ]],
    ["talent_acquisition", [
      "talent acquisition", "recruiting", "recruitment",
      "university recruiting"
    ]],
    ["hris", [
      "hris", "human resources information system"
    ]],
    ["employee_experience", [
      "employee engagement", "employee experience",
      "talent development", "learning and development"
    ]]
  ];

  for (const [profile, phrases] of exactTitleRules) {
    if (phrases.some((phrase) => title.includes(phrase))) {
      return {
        profile,
        source: "title_exact"
      };
    }
  }

  if (
    title.includes("human resources") ||
    title.includes("hr intern") ||
    title.includes("hr internship") ||
    title.includes("hr co-op")
  ) {
    const strongDescriptionProfiles = [
      ["people_analytics", [
        "people analytics team",
        "workforce analytics team",
        "predictive workforce",
        "people data science"
      ]],
      ["total_rewards", [
        "total rewards team",
        "compensation analysis",
        "benefits administration"
      ]],
      ["talent_acquisition", [
        "talent acquisition team",
        "candidate sourcing",
        "recruiting operations"
      ]],
      ["hris", [
        "hris implementation",
        "hr information systems",
        "employee data administration"
      ]]
    ];

    for (const [profile, phrases] of strongDescriptionProfiles) {
      if (phrases.some((phrase) => description.includes(phrase))) {
        return {
          profile,
          source: "description_strong"
        };
      }
    }

    return {
      profile: "general_hr",
      source: "broad_hr_title"
    };
  }

  const weightedProfiles = {
    people_analytics: [
      "people analytics", "workforce analytics", "people data",
      "workforce data", "predictive model", "dashboard",
      "power bi", "tableau", "python"
    ],
    total_rewards: [
      "total rewards", "compensation", "benefits",
      "payroll", "open enrollment"
    ],
    talent_acquisition: [
      "talent acquisition", "recruiting", "sourcing",
      "candidate", "interview scheduling"
    ],
    hris: [
      "hris", "employee data", "data entry",
      "system implementation", "data quality"
    ],
    employee_experience: [
      "employee experience", "employee engagement",
      "recognition", "internal communication", "culture"
    ],
    hr_operations: [
      "hr operations", "onboarding", "employee records",
      "personnel files", "compliance", "hr administration"
    ],
    general_hr: [
      "human resources", "hr support", "hr intern"
    ]
  };

  let bestProfile = "general_hr";
  let bestScore = -1;
  const scores = {};

  for (const [profile, phrases] of Object.entries(weightedProfiles)) {
    let score = 0;

    for (const phrase of phrases) {
      if (description.includes(phrase)) {
        score += phrase.includes(" ") ? 3 : 1;
      }
    }

    scores[profile] = score;

    if (score > bestScore) {
      bestScore = score;
      bestProfile = profile;
    }
  }

  return {
    profile: bestProfile,
    source: "weighted_description",
    scores
  };
}

