function clean(value) {
  return String(value || "")
    .replace(/\r/g, "\n")
    .replace(/[ \t]+/g, " ")
    .replace(/\n{3,}/g, "\n\n")
    .trim();
}

function inline(value) {
  return clean(value).replace(/\s+/g, " ").trim();
}

function norm(value) {
  return inline(value)
    .toLowerCase()
    .replace(/&/g, " and ")
    .replace(/[\/|_\-–—]+/g, " ")
    .replace(/[^a-z0-9 ]+/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

function first(...values) {
  for (const value of values) {
    const text = clean(value);
    if (text && !["not specified", "not listed", "n/a", "none"].includes(text.toLowerCase())) return text;
  }
  return "";
}

function url(value) {
  const match = String(value || "").match(/https?:\/\/[^\s]+/i);
  return match ? match[0].replace(/[),.;]+$/, "") : "";
}

function hash(value) {
  let output = 0;
  for (const character of String(value || "")) {
    output = ((output << 5) - output) + character.charCodeAt(0);
    output |= 0;
  }
  return Math.abs(output).toString(16).slice(0, 10);
}

const ALIASES = {
  title: ["job title", "title"],
  company_name: ["company name", "company"],
  location: ["location"],
  work_arrangement: ["remote hybrid onsite", "work arrangement"],
  employment_type: ["internship part time full time", "employment type", "job type"],
  salary: ["pay wage salary", "salary", "compensation"],
  posted_date: ["posted date", "date posted"],
  apply_deadline: ["apply deadline", "application deadline"],
  start_date: ["start date"],
  end_date: ["end date"],
