  industry: ["industry"],
  company_size: ["company size"],
  application_link: ["application link", "apply link", "job link"],
  employer_description: ["employer description", "company description"]
};

const LOOKUP = {};
Object.entries(ALIASES).forEach(([key, aliases]) => aliases.forEach(alias => { LOOKUP[norm(alias)] = key; }));

function parseSections(raw) {
  const sections = {};
  let current = null;
  let lines = [];
  const scalar = new Set([
    "title", "company_name", "location", "work_arrangement", "employment_type",
    "salary", "posted_date", "apply_deadline", "start_date", "end_date",
    "hours_per_week", "job_description", "work_authorization", "industry",
    "company_size", "application_link", "employer_description"
  ]);

  function flush() {
    if (!current) return;
    const value = clean(lines.join("\n"));
    if (value) {
      if (scalar.has(current)) {
        if (!sections[current]) sections[current] = value;
      } else {
        sections[current] = clean([sections[current] || "", value].filter(Boolean).join("\n"));
      }
    }
    current = null;
    lines = [];
  }

  clean(raw).split("\n").forEach(rawLine => {
    const line = rawLine.replace(/\s+$/, "");
    const match = line.match(/^\s*([^:\n]{1,100})\s*:\s*(.*)$/);
    if (match) {
      const key = LOOKUP[norm(match[1])];
      if (key) {
        flush();
        current = key;
        if (match[2].trim()) lines.push(match[2].trim());
        return;
      }
    }
    if (current) lines.push(line);
  });
  flush();
  return sections;
}

function bullets(value) {
  const rawLines = clean(value).split("\n");
  const output = [];
  rawLines.forEach(line => {
    const trimmed = line.trim();
    if (!trimmed) return;
    const bulletMatch = trimmed.match(/^[•●▪◦*\-–—]+\s*(.+)$/);
    if (bulletMatch) output.push(inline(bulletMatch[1]));
    else if (rawLines.length === 1) output.push(inline(trimmed));
  });
  return [...new Set(output.filter(Boolean))];
}

function cptRisk(workAuth) {
  const text = inline(workAuth).toLowerCase();
  if (/citizen(ship)? required|green card required/.test(text)) {
    return { cpt_risk: "high", cpt_review_required: true, notes: "Citizenship or permanent-resident restriction detected." };
  }
  if (/authorized to work|no sponsorship|sponsorship is not available|visa sponsorship/.test(text)) {
    return { cpt_risk: "review_required", cpt_review_required: true, notes: "Work authorization language requires CPT review." };
  }
  if (/cpt|opt/.test(text)) {
    return { cpt_risk: "review_required", cpt_review_required: true, notes: "CPT/OPT language detected; verify eligibility." };
  }
  return { cpt_risk: "unknown_review", cpt_review_required: true, notes: "Work authorization is not conclusive." };
}

