function ajrNorm(s) {
  return String(s || '').toLowerCase().replace(/[^a-z0-9+#.%]+/g, ' ').replace(/\s+/g, ' ').trim();
}
function ajrWalk(v, path=[], out=[]) {
  if (Array.isArray(v)) v.forEach((x,i)=>ajrWalk(x,path.concat(String(i)),out));
  else if (v && typeof v === 'object') Object.entries(v).forEach(([k,x])=>{
    out.push({path:path.concat(k),key:k,value:x});
    ajrWalk(x,path.concat(k),out);
  });
  return out;
}
function ajrIsJDKey(k) {
  const x = ajrNorm(k).replace(/\s/g,'_');
  return ['description','job_description','jobdescription','full_job_description','raw_description','jd','posting_text','job_text'].includes(x);
}
function ajrFindJD(o) {
  const h = ajrWalk(o).filter(x=>ajrIsJDKey(x.key)&&typeof x.value==='string'&&x.value.length>200);
  h.sort((a,b)=>b.value.length-a.value.length);
  return h.length ? h[0].value : '';
}
function ajrEvidence(o) {
  const parts=[];
  for (const x of ajrWalk(o)) {
    if (ajrIsJDKey(x.key) || typeof x.value !== 'string') continue;
    const p = x.path.map(ajrNorm).join(' ');
    if (/fact|evidence|verified|approved|adjacent|resume|experience|skill|bullet|summary|achievement|project|company|reviewed|bank/.test(p)) parts.push(x.value);
  }
  return ajrNorm(parts.join(' '));
}
function ajrRefs(o) {
  const refs=[];
  function rec(v) {
    if (!v || typeof v !== 'object') return;
    if (Array.isArray(v)) { v.forEach(rec); return; }
    for (const k of Object.keys(v)) {
      if (typeof v[k] === 'string' && /summary|skills?|bullet|experience|project/.test(ajrNorm(k))) refs.push({parent:v,key:k});
      else rec(v[k]);
    }
  }
  rec(o);
  return refs;
}
function ajrResume(o) {
  return ajrNorm(ajrRefs(o).map(r=>r.parent[r.key]).join(' '));
}
function ajrHas(text, phrases) {
  const n=ajrNorm(text);
  return phrases.some(p=>n.includes(ajrNorm(p)));
}
function ajrUnique(values) {
  const seen=new Set(), out=[];
  for (const v of values) {
    const s=String(v||'').trim().replace(/\s+/g,' '), k=ajrNorm(s);
    if (s && !seen.has(k)) { seen.add(k); out.push(s); }
  }
  return out;
}
function ajrTrim(s,n) {
  s=String(s||'').replace(/\s+/g,' ').trim();
  if (s.length<=n) return s;
  const c=s.slice(0,n-1), i=Math.max(c.lastIndexOf('|'),c.lastIndexOf(';'),c.lastIndexOf(','),c.lastIndexOf(' '));
  return c.slice(0,i>n*.65?i:n-1).replace(/[|;, ]+$/,'');
}
function ajrLedgerTerms(o) {
  const out=[];
  for (const x of ajrWalk(o)) {
    const v=x.value;
    if (!v || typeof v !== 'object' || Array.isArray(v)) continue;
    const term=v.canonical||v.term||v.keyword||v.phrase||v.skill;
    if (typeof term !== 'string' || term.length<2 || term.length>80) continue;
    const weight=Number(v.weight||v.points||v.score_weight||v.keyword_weight||0);
    const missing = v.missing===true || v.present===false || v.matched===false || v.covered===false ||
      (Array.isArray(v.missing_targets)&&v.missing_targets.length>0);
    const supported = v.supported===true || v.verified===true || v.evidence_integrity===100 ||
      /verified|adjacent|supported/.test(ajrNorm(v.evidence_path||v.evidence_mode||''));
    if (missing || weight>0) out.push({term:String(term),weight:Number.isFinite(weight)?weight:0,missing,supported,source:'existing_ledger'});
  }
