}
function ajrExactEvidencePhrases(jd,evidence) {
  const words=ajrNorm(jd).split(' ').filter(w=>w.length>2&&!AJR_STOP.has(w));
  const candidates=[];
  for (let n=4;n>=2;n--) {
    for (let i=0;i<=words.length-n;i++) {
      const phrase=words.slice(i,i+n).join(' ');
      if (phrase.length<8 || phrase.length>60) continue;
      if (ajrNorm(evidence).includes(phrase)) candidates.push(phrase);
    }
  }
  return ajrUnique(candidates).slice(0,30);
}
function ajrDiagnostic(o) {
  const jd=ajrFindJD(o), evidence=ajrEvidence(o), resume=ajrResume(o);
  const rows=[];
  for (const [term,jdVars,eVars] of AJR_LEXICON) {
    const requested=ajrHas(jd,jdVars);
    const present=ajrHas(resume,[term].concat(jdVars));
    const supported=ajrHas(evidence,eVars)||present;
    if (requested) rows.push({term,requested,present,supported,source:'lexicon'});
  }
  for (const row of ajrLedgerTerms(o)) {
    const present=ajrHas(resume,[row.term]);
    const supported=row.supported||ajrHas(evidence,[row.term]);
    rows.push({term:row.term,requested:true,present,supported,weight:row.weight,source:row.source});
  }
  for (const phrase of ajrExactEvidencePhrases(jd,evidence)) {
    rows.push({term:phrase,requested:true,present:ajrHas(resume,[phrase]),supported:true,weight:0,source:'exact_jd_evidence_intersection'});
  }
  const dedup={};
  for (const row of rows) {
    const k=ajrNorm(row.term);
    if (!dedup[k]) dedup[k]=row;
    else {
      dedup[k].present=dedup[k].present||row.present;
      dedup[k].supported=dedup[k].supported||row.supported;
      dedup[k].weight=Math.max(dedup[k].weight||0,row.weight||0);
      dedup[k].source=dedup[k].source+'+'+row.source;
    }
  }
  const all=Object.values(dedup);
  all.sort((a,b)=>(b.weight||0)-(a.weight||0));
  return {
    rows:all,
    supported_missing:all.filter(x=>x.requested&&x.supported&&!x.present).map(x=>x.term),
    unsupported_missing:all.filter(x=>x.requested&&!x.supported&&!x.present).map(x=>x.term),
    present:all.filter(x=>x.present).map(x=>x.term)
  };
}
function ajrFindRef(refs,patterns) {
  for (const p of patterns) {
    const hit=refs.find(r=>p.test(String(r.key)));
    if (hit) return hit;
  }
  return null;
}
function ajrApply(o) {
