function termPresent(
  term,
  resumeTextValue
) {
  const normalizedTerm =
    cleanText(term).toLowerCase();

  const aliasGroups = {
    "human resources": [
      "human resources",
      "human resource",
      "hr operations",
      "hr "
    ],

    "hr operations": [
      "hr operations",
      "human resources operations",
      "hr service"
    ],

    "recruiting": [
      "recruiting",
