    ],

    "confidential": [
      "confidential",
      "confidentiality",
      "data privacy"
    ],

    "stakeholder": [
      "stakeholder",
      "hiring-team",
      "cross-functional"
    ],

    "interview scheduling": [
      "interview scheduling",
      "interview coordination",
      "calendar management"
    ],

    "pre-employment": [
      "pre-employment",
      "background-check"
    ],

    "hr reporting": [
      "hr reporting",
      "workforce reporting",
      "reporting"
    ],

    "employee support": [
      "employee support",
      "employee inquiries",
      "internal requests",
      "hr service"
    ],

    "data entry": [
      "data entry",
      "data updates",
      "record updates"
    ],

    "data quality": [
      "data quality",
      "data validation",
      "accuracy"
    ]
  };

  const alternatives =
    aliasGroups[normalizedTerm] ||
    [normalizedTerm];

  return alternatives.some(
    (alternative) =>
      resumeTextValue.includes(
        alternative
      )
  );
}

const missingTerms = criticalTerms.filter(
  (term) =>
    !termPresent(
      term,
      lowerResume
    )
);

const criticalCoverage = (() => {
  if (!criticalTerms.length) {
    return 1;
  }

  if (!usingV9TermAuthority) {
    return (
      criticalTerms.length -
      missingTerms.length
    ) / criticalTerms.length;
  }

  const totalWeight =
    v9CriticalRows.reduce(
      (sum, row) =>
        sum +
        Number(row?.weight || 0),
      0
    );

  if (!totalWeight) {
    return 1;
  }

  const coveredWeight =
    v9CriticalRows.reduce(
      (sum, row) => {
        const phrase =
          cleanText(
            row.exact_jd_phrase ||
            row.canonical
          );

        return (
          sum +
          (
            phrase &&
            termPresent(
              phrase,
              lowerResume
            )
              ? Number(
                  row?.weight || 0
                )
              : 0
          )
        );
      },
      0
    );

  return (
    coveredWeight /
    totalWeight
  );
})();

