            (
              row?.support_mode ===
                "exposure" ||
              row?.support_level ===
                "familiarity" ||
              row?.allowed_claim_style ===
                "familiarity_only"
            )
        )
    : [];

const exposureTools =
  unique(
    exposureRows.map(
