const exposureOverclaims =
  exposureTools.filter(
    tool =>
      Array.from(
        NARRATIVE_FIELDS
      ).some(
        key => {
          const text =
            cleanText(
              fields[key]
            );

          if (
            !text
              .toLowerCase()
              .includes(
                tool.toLowerCase()
              )
          ) {
            return false;
          }

          const escaped =
            tool.replace(
              /[.*+?^${}()|[\]\\]/g,
              "\\$&"
            );

          const safe =
            new RegExp(
              `(?:familiarity|familiar|exposure|concepts?)\\s+(?:with|to)?\\s*${escaped}|${escaped}\\s+(?:familiarity|concepts?|exposure)`,
              "i"
            );

          if (safe.test(text)) {
            return false;
          }

          return /\b(?:proficient|proficiency|skilled|experienced|experience|hands-on|advanced|expert|implemented|configured|administered|owned|managed|used|using)\b/i
            .test(text);
        }
      )
  );

