const duplicateSkillCount =
  skillTerms.length -
  new Set(
    skillTerms.map(
      (term) =>
        term.toLowerCase()
    )
  ).size;

const metricText = [
  ...experienceValues,
  ...projectValues
].join(" ");

const metricCount =
  numericTokens(
