const quality = {
  canonical_field_count:
    Object.keys(fields).length ===
    CANONICAL_FIELDS.length,

  required_fields:
    missingCore.length === 0,

  summary:
    cleanText(
      fields.SUMMARY
    ).length >= 300 &&
    cleanText(
      fields.SUMMARY
    ).length <= 345 &&
    sentenceLooksComplete(
      fields.SUMMARY,
      "SUMMARY"
    ),

  language:
    Array.from(
      NARRATIVE_FIELDS
    ).every(
      (key) =>
        !cleanText(
          fields[key]
        ) ||
        sentenceLooksComplete(
          fields[key],
          key
        )
    ),

  numeric:
    unsupportedNumbers.length === 0,

  stuffing:
    duplicateSkillCount <= 2,

  visual_fullness:
    finalChars >= 3550 &&
    finalChars <= 3660,

  preferred_fullness:
    finalChars >= 3620 &&
    finalChars <= 3660,

  experience_depth:
    experienceValues.length >= 6 &&
    averageExperienceChars >= 125,

  bullet_quality:
    experienceValues.every(
      (value) =>
        value.length >= 115 &&
        value.length <= 190
    ) &&
    projectValues.length === 4 &&
    projectValues.every(
      (value) =>
        value.length >= 100 &&
        value.length <= 190
    ),

  role_balance:
    projectChars === 0 ||
    (
      experienceChars /
      projectChars
    ) >= roleBalanceThreshold,

  metrics:
    metricCount >= 4 &&
    metricCount <= 18,

  placement:
    placementGaps.length === 0,

  alignment:
    criticalCoverage >= 0.9 &&
    keywordScaled >= 0.72
};

const phraseAndKeywordPoints =
  Math.round(
    22 * criticalCoverage +
    13 * keywordScaled
  );

const criticalPoints =
  Math.round(
    15 * criticalCoverage
  );

const evidencePoints =
  evidenceIntegrity === 100
    ? 15
    : 0;

const placementPoints =
  quality.placement
    ? 10
    : Math.max(
        0,
        10 -
        placementGaps.length * 5
      );

const rolePoints =
  Math.round(
    10 *
    (
      [
        quality.alignment,
        quality.role_balance,
        quality.experience_depth
      ].filter(Boolean).length /
      3
    )
  );

const languagePoints =
  Math.round(
    10 *
    (
      [
        quality.summary,
        quality.language,
        quality.bullet_quality,
        quality.stuffing
      ].filter(Boolean).length /
      4
    )
  );

const formatPoints =
  Math.round(
    5 *
    (
      [
        quality.canonical_field_count,
        quality.required_fields,
        quality.visual_fullness,
        quality.metrics
      ].filter(Boolean).length /
      4
    )
  );

let score =
  phraseAndKeywordPoints +
  criticalPoints +
  evidencePoints +
  placementPoints +
  rolePoints +
  languagePoints +
  formatPoints;

if (!quality.required_fields) {
  score = Math.min(
    score,
    70
  );
}

if (!quality.canonical_field_count) {
  score = Math.min(
    score,
    70
  );
}

if (
  !quality.language ||
  !quality.summary
) {
  score = Math.min(
    score,
    84
  );
}

if (!quality.numeric) {
  score = Math.min(
    score,
    79
  );
}

if (!quality.stuffing) {
  score = Math.min(
    score,
    89
  );
}

if (!quality.visual_fullness) {
  score = Math.min(
    score,
    92
  );
} else if (
  !quality.preferred_fullness
) {
  // Truth-safe but slightly under the preferred full-page target
  // should not be treated like a page-fit failure.
  score = Math.min(
    score,
    96
  );
}

if (!quality.experience_depth) {
  score = Math.min(
    score,
    92
  );
}

if (!quality.bullet_quality) {
  score = Math.min(
    score,
    92
  );
}

if (!quality.role_balance) {
  score = Math.min(
    score,
    93
  );
}

if (!quality.alignment) {
  score = Math.min(
    score,
    94
  );
}

if (!quality.metrics) {
  score = Math.min(
    score,
    92
  );
}

if (
  evidenceIntegrity < 100
) {
  score = Math.min(
    score,
    89
  );
}

if (
  missingTerms.length
) {
  score = Math.min(
    score,
    94
  );
}

score = Math.max(
  0,
  Math.min(
    98,
    score
  )
);

assignFieldAliases(
  item,
  fields
);

item.ats_resume_score =
