/**
 * Prepare HR Agent Payload V7.8 Final — V2
 *
 * Fixes:
 * 1. Searches current input recursively for resume markdown and template fields.
 * 2. Safely checks important upstream nodes for the complete resume state.
 * 3. Parses JSON-encoded field objects when present.
 * 4. Does not let an empty first resume object hide populated alternatives.
 * 5. Reconstructs the resume from the complete 44-field template contract.
 */

function cleanText(value) {
  if (value === null || value === undefined) return "";

  return String(value)
    .replace(/\r/g, "")
    .replace(/\u0000/g, "")
    .replace(/[ \t]+\n/g, "\n")
    .replace(/\n{3,}/g, "\n\n")
    .trim();
}

function isObject(value) {
  return Boolean(
    value &&
    typeof value === "object" &&
    !Array.isArray(value)
  );
}

function safeJsonParse(value) {
  if (typeof value !== "string") return null;

  const text = value.trim();

  if (
    !text ||
    (!text.startsWith("{") && !text.startsWith("["))
  ) {
    return null;
  }

  try {
    return JSON.parse(text);
  } catch {
    return null;
  }
}

function safeNodeItems(nodeName) {
  try {
    const items = $items(nodeName);

    return Array.isArray(items)
      ? items
          .map(item => item?.json)
          .filter(isObject)
      : [];
  } catch {
    return [];
  }
}

function objectHasUsefulData(value) {
  if (!isObject(value)) return false;

  return Object.values(value).some(entry => {
    if (typeof entry === "string") {
      return cleanText(entry).length > 0;
    }

    if (Array.isArray(entry)) {
      return entry.length > 0;
    }

    return isObject(entry) && Object.keys(entry).length > 0;
  });
}

function walk(value, visitor, depth = 0, seen = new Set()) {
  if (depth > 12) return;

  if (isObject(value) || Array.isArray(value)) {
    if (seen.has(value)) return;
    seen.add(value);
  }

  visitor(value);

  if (Array.isArray(value)) {
    value.forEach(child => {
      walk(child, visitor, depth + 1, seen);
    });

    return;
  }

  if (isObject(value)) {
    Object.values(value).forEach(child => {
      walk(child, visitor, depth + 1, seen);
    });
  }
}

function collectNamedValues(root, wantedKeys) {
  const results = [];

  walk(root, value => {
    if (!isObject(value)) return;

    Object.entries(value).forEach(([key, child]) => {
      if (!wantedKeys.has(key)) return;

      if (typeof child === "string") {
        const cleaned = cleanText(child);

        if (cleaned) {
          results.push(cleaned);
        }

        const parsed = safeJsonParse(child);

        if (parsed !== null) {
          results.push(parsed);
        }
      } else if (child !== null && child !== undefined) {
        results.push(child);
      }
    });
  });

  return results;
}

