    return;
  }

  if (!isObject(container)) return;

  Object.entries(container).forEach(([key, value]) => {
    if (
      typeof value === "string" ||
      typeof value === "number" ||
      typeof value === "boolean"
    ) {
      assignField(key, value);
    }
  });
}

