function extractCandidate(root) {
  const queue = [root];
  const seen = new Set();

  while (queue.length) {
    let value = queue.shift();

    if (value === null || value === undefined) continue;

    if (typeof value === "string") {
      const cleaned = value
        .replace(/^```(?:json)?\s*/i, "")
        .replace(/\s*```$/i, "")
        .trim();

      try {
        value = JSON.parse(cleaned);
      } catch (_) {
        continue;
      }
    }

    if (
      !value ||
      typeof value !== "object" ||
      seen.has(value)
    ) {
      continue;
    }

    seen.add(value);

    if (isObject(value.improved_fields)) {
      return value;
    }

    if (
      isObject(value.output) &&
      isObject(value.output.improved_fields)
    ) {
      return value.output;
    }

    for (const child of Object.values(value)) {
      queue.push(child);
    }
  }

  return null;
}

function sentenceLooksComplete(value, key) {
  const text = cleanText(value);

  if (!text) return false;

  const listField = [
    "COURSEWORK",
    "DATA_ANALYTICS_SKILLS",
    "HR_OPERATIONS_SKILLS",
    "COMPLIANCE_TOOLS"
  ].includes(key);

  if (listField) {
    return text.split(",").map(cleanText).filter(Boolean).length >= 3;
  }

  if (
    /\b(?:and|or|with|for|to|of|in|by|using)\s+\d[\d,.%+]*\.?$/i.test(text)
  ) {
    return false;
  }

  if (
    /\b(?:and|or|with|for|to|of|in|by|using)\.?$/i.test(text)
  ) {
    return false;
  }

  if (/\b\d[\d,]*\.?$/.test(text) && !/[+%]$/.test(text)) {
    return false;
  }

  return text.split(/\s+/).filter(Boolean).length >= 5;
}

function numericIntegrity(value, approvedNumbers) {
  return numericTokens(value).every(
    (token) => approvedNumbers.has(token)
  );
}

function containsUnsupportedSystem(value, evidenceText) {
  const riskySystems = [
    "sap",
    "kronos",
    "adp",
    "ukg",
    "oracle hcm",
    "peoplesoft",
    "icims",
    "jobvite",
    "workday",
    "successfactors",
    "bamboohr",
    "greenhouse"
  ];

  const lowerValue = cleanText(value).toLowerCase();
  const lowerEvidence = cleanText(evidenceText).toLowerCase();

  for (const system of riskySystems) {
    if (
      lowerValue.includes(system) &&
      !lowerEvidence.includes(system)
    ) {
      return system;
    }
  }

  return "";
}

