    ],
    hr_operations: [
      "hr operations", "human resources operations", "onboarding",
      "employee records", "personnel files", "compliance",
      "employee inquiries", "hr administration", "people partner"
    ],
    general_hr: [
      "human resources", "hr intern", "hr co-op"
    ]
  };

  let best = "general_hr";
  let bestScore = -1;
  const scores = {};

  for (const [profile, terms] of Object.entries(profiles)) {
    let score = 0;

    for (const term of terms) {
      if (lower.includes(term)) {
        score += term.includes(" ") ? 3 : 1;
      }
    }

    scores[profile] = score;

    if (score > bestScore) {
      bestScore = score;
      best = profile;
    }
  }

  return { profile: best, scores };
}

