function clean(v) {
  return String(v ?? "").trim();
}
function bool(v, fallback = false) {
  if (typeof v === "boolean") return v;
  const t = clean(v).toLowerCase();
  if (["true","1","yes","on"].includes(t)) return true;
  if (["false","0","no","off"].includes(t)) return false;
  return fallback;
}

