function cleanText(value) {
  return String(value ?? "")
    .replace(/\u00a0/g, " ")
    .replace(/[\u2013\u2014]/g, " - ")
    .replace(/[\u2018\u2019]/g, "'")
    .replace(/[\u201c\u201d]/g, '"')
    .replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/g, " ")
    .replace(/[\u200B-\u200D\u2060\uFEFF]/g, "")
    .replace(/\s+/g, " ")
    .replace(/\s+([,.;:!?])/g, "$1")
    .trim();
}

function isObject(value) {
  return Boolean(
    value &&
    typeof value === "object" &&
    !Array.isArray(value)
  );
}

function asObject(value) {
  if (isObject(value)) return value;

  if (typeof value === "string" && value.trim()) {
    try {
      const parsed = JSON.parse(value);
      return isObject(parsed) ? parsed : {};
    } catch (_) {}
  }

  return {};
}

function deepClone(value) {
  return JSON.parse(JSON.stringify(value ?? {}));
}

function unique(values) {
  const seen = new Set();
  const output = [];

  for (const raw of values || []) {
    const value = cleanText(raw);
    const key = value.toLowerCase();

    if (value && !seen.has(key)) {
      seen.add(key);
      output.push(value);
    }
  }

  return output;
}

function numericTokens(text) {
  return unique(
    cleanText(text).match(
      /\d[\d,]*(?:\.\d+)?(?:%|\+)?/g
    ) || []
  );
}

function tokenSet(text) {
  return new Set(
    cleanText(text)
      .toLowerCase()
      .match(/[a-z][a-z0-9+#./-]{2,}/g) || []
  );
}

function totalChars(fields) {
  return CANONICAL_FIELDS.reduce(
    (sum, key) => sum + cleanText(fields?.[key]).length,
    0
  );
}

function canonicalizeFields(source) {
  const objectValue = asObject(source);
  const output = {};

  for (const key of CANONICAL_FIELDS) {
    output[key] = cleanText(objectValue[key]);
  }

  return output;
}

function populatedFieldCount(fields) {
  return CANONICAL_FIELDS.filter(
    (key) => cleanText(fields?.[key])
  ).length;
}

function missingRequired(fields) {
  return REQUIRED_FIELDS.filter(
    (key) => !cleanText(fields?.[key])
  );
}

function stableFields(fields) {
  const output = {};

  for (const key of CANONICAL_FIELDS) {
    output[key] = cleanText(fields?.[key]);
  }

  return output;
}

function hashFields(fields) {
  const input = JSON.stringify(stableFields(fields));
  let hash = 0x811c9dc5;

  for (let index = 0; index < input.length; index += 1) {
    hash ^= input.charCodeAt(index);
    hash = Math.imul(hash, 0x01000193) >>> 0;
  }

  return `fnv1a32:${hash.toString(16).padStart(8, "0")}:${input.length}`;
}


