function detectRoleProfile(text) {
  const lower = cleanText(text).toLowerCase();

  const profiles = {
    people_analytics: [
      "people analytics", "workforce analytics", "people data",
      "workforce data", "predictive", "dashboard", "tableau",
      "power bi", "python", "data analysis"
    ],
    total_rewards: [
      "total rewards", "compensation", "benefits", "payroll",
      "salary", "open enrollment", "reward"
    ],
    talent_acquisition: [
      "talent acquisition", "recruiting", "recruitment",
      "sourcing", "candidate", "interview", "university recruiting"
    ],
    hris: [
      "hris", "human resources information system", "workday",
      "successfactors", "bamboohr", "data entry",
      "system implementation", "employee data"
    ],
    employee_experience: [
      "employee experience", "engagement", "culture",
      "recognition", "internal communication",
      "learning and development", "talent development"
    ],
    hr_operations: [
      "hr operations", "human resources operations", "onboarding",
      "employee records", "personnel files", "compliance",
      "employee inquiries", "hr administration", "people partner"
    ],
    general_hr: [
      "human resources", "hr intern", "hr co-op"
    ]
  };

  let best = "general_hr";
  let bestScore = -1;
  const scores = {};

  for (const [profile, terms] of Object.entries(profiles)) {
    let score = 0;

    for (const term of terms) {
      if (lower.includes(term)) {
        score += term.includes(" ") ? 3 : 1;
      }
    }

    scores[profile] = score;

    if (score > bestScore) {
      bestScore = score;
      best = profile;
    }
  }

  return { profile: best, scores };
}

