  for (const source of sources) {
    if (!isObject(source)) continue;
    for (const key of CANONICAL_FIELDS) {
      if (!out[key] && clean(source[key])) {
        out[key] = clean(source[key]);
      }
    }
  }

  return out;
}

function walk(value, path = [], out = [], seen = new Set()) {
  if (!value || typeof value !== "object" || seen.has(value)) return out;
  seen.add(value);

  if (Array.isArray(value)) {
    value.forEach((child, index) => walk(child, path.concat(String(index)), out, seen));
    return out;
  }

  for (const [key, child] of Object.entries(value)) {
    out.push({ path: path.concat(key), key, value: child });
    if (child && typeof child === "object") {
      walk(child, path.concat(key), out, seen);
    }
  }

  return out;
}

function findFullJD(root) {
  const direct = [
    root.current_job?.description,
    root.current_job?.job_description,
    root.source_job?.description,
    root.job?.description,
    root.manual_job?.description,
    root.config?.manual_job?.description,
    root.scored_jobs?.[0]?.source_job?.description,
    root.resume_candidates?.[0]?.source_job?.description,
    root.filtered_jobs?.[0]?.description,
    root.jobs?.[0]?.description,
    root.raw_jobs?.[0]?.description,
    root.normalized_jobs?.[0]?.description,
    root.full_job_description,
    root.job_description,
    root.description_raw,
    root.manual_job_text,
    root.description
  ].map(clean).filter(text => text.length >= 120);

  if (direct.length) {
    return direct.sort((a, b) => b.length - a.length)[0];
  }

  const wanted = new Set([
    "description", "job_description", "jobdescription",
    "full_job_description", "raw_description",
    "jd", "posting_text", "job_text"
  ]);

  const hits = walk(root)
    .filter(entry =>
      wanted.has(norm(entry.key).replace(/\s/g, "_")) &&
      typeof entry.value === "string"
    )
    .map(entry => clean(entry.value))
    .filter(text => text.length >= 120)
    .sort((a, b) => b.length - a.length);

  return hits[0] || "";
}

function findJobMeta(root) {
