}

function occurrences(text, phrase) {
  const hay = ` ${norm(text)} `;
  const needle = norm(phrase);
  if (!needle) return 0;

  // V9.2.3 exact token/phrase boundary matching.
  // Prevents false tool hits such as Lever matching "leveraging".
  const escaped = needle.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  const pattern = new RegExp(`(^|[^a-z0-9+#.%/-])${escaped}(?=$|[^a-z0-9+#.%/-])`, "g");
  return [...hay.matchAll(pattern)].length;
}

