    .filter(row => row.count > 0)
    .sort((a, b) => (b.count - a.count) || (b.variant.length - a.variant.length));

  if (!hits.length) continue;

  const exact = hits[0].variant;
  const totalOccurrenceCount = hits.reduce((sum, row) => sum + row.count, 0);
  const support = supportFor(canonical, variants);

  ledger.push({
    canonical,
    exact_jd_phrase: exact,
    family,
    occurrence_count: totalOccurrenceCount,
    weight: Math.min(15, baseWeight + Math.max(0, totalOccurrenceCount - 1)),
    named_tool: false,
    ...support
  });
