const CANONICAL_FIELDS = [
  "NAME", "LOCATION", "PHONE", "EMAIL", "LINKEDIN", "GITHUB",
  "SUMMARY",
  "MASTERS_SCHOOL", "MASTERS_LOCATION", "MASTERS_DEGREE",
  "MASTERS_GPA", "COURSEWORK",
  "BACHELORS_SCHOOL", "BACHELORS_LOCATION", "BACHELORS_DEGREE",
  "BACHELORS_GPA",
  "DATA_ANALYTICS_SKILLS", "HR_OPERATIONS_SKILLS", "COMPLIANCE_TOOLS",
  "CERT_1", "CERT_2", "CERT_3", "CERT_4", "CERT_5",
  "PROJECT_1_NAME", "PROJECT_1_TOOLS",
  "PROJECT_1_BULLET_1", "PROJECT_1_BULLET_2",
  "PROJECT_2_NAME", "PROJECT_2_TOOLS",
  "PROJECT_2_BULLET_1", "PROJECT_2_BULLET_2",
  "COMPANY_1", "DATE_1", "ROLE_1",
  "COMPANY_1_BULLET_1", "COMPANY_1_BULLET_2",
  "COMPANY_1_BULLET_3", "COMPANY_1_BULLET_4",
  "COMPANY_2", "DATE_2", "ROLE_2",
  "COMPANY_2_BULLET_1", "COMPANY_2_BULLET_2",
  "COMPANY_2_BULLET_3"
];

const NARRATIVE_FIELDS = [
  "SUMMARY",
  "PROJECT_1_BULLET_1", "PROJECT_1_BULLET_2",
  "PROJECT_2_BULLET_1", "PROJECT_2_BULLET_2",
  "COMPANY_1_BULLET_1", "COMPANY_1_BULLET_2",
  "COMPANY_1_BULLET_3", "COMPANY_1_BULLET_4",
  "COMPANY_2_BULLET_1", "COMPANY_2_BULLET_2",
  "COMPANY_2_BULLET_3"
];

const SKILL_FIELDS = [
  "DATA_ANALYTICS_SKILLS", "HR_OPERATIONS_SKILLS", "COMPLIANCE_TOOLS"
];

function clean(value) {
  return String(value ?? "")
    .replace(/\u00a0/g, " ")
    .replace(/[\u2013\u2014]/g, " - ")
    .replace(/[\u2018\u2019]/g, "'")
    .replace(/[\u201c\u201d]/g, '"')
    .replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/g, " ")
    .replace(/[\u200B-\u200D\u2060\uFEFF]/g, "")
    .replace(/\s+/g, " ")
    .replace(/\s+([,.;:!?])/g, "$1")
    .trim();
}

function norm(value) {
  return clean(value)
    .toLowerCase()
    .replace(/[^a-z0-9+#.%/-]+/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

function isObject(value) {
  return Boolean(value && typeof value === "object" && !Array.isArray(value));
}

function clone(value) {
  return JSON.parse(JSON.stringify(value ?? {}));
}

function unique(values) {
  const seen = new Set();
  const out = [];
  for (const raw of values || []) {
    const value = clean(raw);
    const key = norm(value);
    if (value && key && !seen.has(key)) {
      seen.add(key);
      out.push(value);
    }
  }
  return out;
}

function stableFields(source) {
  const out = {};
  for (const key of CANONICAL_FIELDS) out[key] = clean(source?.[key]);
  return out;
}

function totalChars(fields) {
  return CANONICAL_FIELDS.reduce((sum, key) => sum + clean(fields?.[key]).length, 0);
}

function hashFields(fields) {
  const input = JSON.stringify(stableFields(fields));
  let hash = 0x811c9dc5;
  for (let i = 0; i < input.length; i += 1) {
    hash ^= input.charCodeAt(i);
    hash = Math.imul(hash, 0x01000193) >>> 0;
  }
  return `fnv1a32:${hash.toString(16).padStart(8, "0")}:${input.length}`;
}

function numericTokens(text) {
  return unique(clean(text).match(/\d[\d,]*(?:\.\d+)?(?:%|\+)?/g) || []);
}

function splitSkills(value) {
  return unique(clean(value).split(/\s*(?:\||,|;)\s*/).filter(Boolean));
}

const PLACEMENT_GROUPS = [
  { name: "summary", fields: ["SUMMARY"], credit: 1.00 },
  {
    name: "experience",
    fields: [
      "COMPANY_1_BULLET_1", "COMPANY_1_BULLET_2",
      "COMPANY_1_BULLET_3", "COMPANY_1_BULLET_4",
      "COMPANY_2_BULLET_1", "COMPANY_2_BULLET_2",
      "COMPANY_2_BULLET_3"
    ],
    credit: 1.00
  },
  {
    name: "project",
    fields: [
      "PROJECT_1_BULLET_1", "PROJECT_1_BULLET_2",
      "PROJECT_2_BULLET_1", "PROJECT_2_BULLET_2"
    ],
    credit: 0.90
  },
  {
    name: "skills",
    fields: [
      "DATA_ANALYTICS_SKILLS",
      "HR_OPERATIONS_SKILLS",
      "COMPLIANCE_TOOLS"
    ],
    credit: 0.55
  },
  { name: "coursework", fields: ["COURSEWORK"], credit: 0.35 }
];

function rowPhrase(row) {
  return norm(row?.exact_jd_phrase || row?.canonical);
}

function placementForRow(row, fields) {
  const phrase = rowPhrase(row);
  if (!phrase) return { credit: 0, fields: [], groups: [] };

  let bestCredit = 0;
  const hitFields = [];
  const hitGroups = [];

  for (const group of PLACEMENT_GROUPS) {
    for (const key of group.fields) {
      if (!norm(fields?.[key]).includes(phrase)) continue;

      hitFields.push(key);
      hitGroups.push(group.name);

      const effectiveCredit =
        row?.named_tool === true && group.name === "skills"
          ? 1.00
          : group.credit;

      bestCredit = Math.max(bestCredit, effectiveCredit);
    }
  }

  return {
    credit: bestCredit,
    fields: unique(hitFields),
    groups: unique(hitGroups)
  };
}

function lexicalCoverage(rows, fields) {
  const totalWeight = rows.reduce(
    (sum, row) => sum + Number(row.weight || 0),
    0
  );
  if (!totalWeight) return 100;

  const resume = norm(
    CANONICAL_FIELDS.map(key => fields[key]).join(" ")
  );

  const coveredWeight = rows.reduce(
    (sum, row) => {
      const phrase = rowPhrase(row);
      return sum + (
        phrase && resume.includes(phrase)
          ? Number(row.weight || 0)
          : 0
      );
    },
    0
  );

  return Math.round(
    (coveredWeight / totalWeight) * 100
  );
}

function weightedCoverage(rows, fields) {
  const totalWeight = rows.reduce(
    (sum, row) => sum + Number(row.weight || 0),
    0
  );
  if (!totalWeight) return 100;

  const creditedWeight = rows.reduce(
    (sum, row) => {
      const placement = placementForRow(row, fields);
      return sum + (
        Number(row.weight || 0) *
        Number(placement.credit || 0)
      );
    },
    0
  );

  return Math.round(
    (creditedWeight / totalWeight) * 100
  );
}

function fieldForRow(row) {
  const family = row?.family || "";
  const term = norm(row?.canonical || row?.exact_jd_phrase || "");

  if (row?.named_tool === true) {
    const hrSystems = [
      "workday", "greenhouse", "bamboohr", "successfactors",
      "adp workforce now", "ukg", "hris", "ats"
    ];
    if (hrSystems.some(tool => term.includes(tool))) {
      return "HR_OPERATIONS_SKILLS";
    }
    return "DATA_ANALYTICS_SKILLS";
  }

  if (family === "people_analytics") return "DATA_ANALYTICS_SKILLS";
  if (["hr_operations", "talent_acquisition", "total_rewards", "employee_experience"].includes(family)) return "HR_OPERATIONS_SKILLS";
  return "COMPLIANCE_TOOLS";
}

function nearDuplicate(a, b) {
  const A = new Set(norm(a).split(" ").filter(word => word.length > 3));
  const B = new Set(norm(b).split(" ").filter(word => word.length > 3));
  if (!A.size || !B.size) return false;
  let common = 0;
  for (const word of A) if (B.has(word)) common += 1;
  return common / Math.min(A.size, B.size) >= 0.78;
}

function fieldLengthOK(key, value) {
  const len = clean(value).length;
  if (key === "SUMMARY") return len >= 240 && len <= 350;
  if (/^COMPANY_[12]_BULLET_/.test(key)) return len >= 115 && len <= 190;
  if (/^PROJECT_[12]_BULLET_/.test(key)) return len >= 100 && len <= 190;
  return true;
}

function syncAliases(target, fields) {
  const exact = stableFields(fields);
  for (const alias of [
    "v9_authoritative_resume_fields", "authoritative_resume_fields", "final_resume_fields",
    "resume_fields", "resume_template_fields", "template_fields", "placeholder_values",
    "doc_fields", "google_doc_fields", "replacements", "fields"
  ]) target[alias] = clone(exact);
  target.authoritative_resume_hash = hashFields(exact);
  target.authoritative_resume_field_chars = totalChars(exact);
  target.authoritative_resume_field_count = CANONICAL_FIELDS.length;
  target.authoritative_resume_populated_field_count = CANONICAL_FIELDS.filter(key => clean(exact[key])).length;
  return exact;
}

function exposureOnlyToolsFromIntel(source) {
  const rows = Array.isArray(source?.v9_jd_intelligence?.weighted_term_ledger)
    ? source.v9_jd_intelligence.weighted_term_ledger
    : [];
  return unique(rows
    .filter(row => row?.named_tool === true && (row?.support_mode === "exposure" || row?.support_level === "familiarity" || row?.allowed_claim_style === "familiarity_only"))
    .map(row => clean(row.canonical || row.exact_jd_phrase)));
}

function exposureOverclaim(value, tools) {
  const text = clean(value);
  for (const tool of tools) {
    if (!norm(text).includes(norm(tool))) continue;
    const escaped = tool.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
    const safe = new RegExp(`(?:familiarity|familiar|exposure|concepts?)\\s+(?:with|to)?\\s*${escaped}|${escaped}\\s+(?:familiarity|concepts?|exposure)`, "i");
    if (safe.test(text)) continue;
    if (/\b(?:proficient|proficiency|skilled|experienced|experience|hands-on|advanced|expert|implemented|configured|administered|owned|managed|used|using)\b/i.test(text)) return tool;
  }
  return "";
}

function summaryIdentityOverclaim(value, labels) {
  const text = norm(value);
  return labels.find(label => {
    const n = norm(label);
    return n && (text.startsWith(`${n} `) || text === n);
  }) || "";
}

const exposureOnlyTools = exposureOnlyToolsFromIntel(item);
const employerIdentityLabels = unique(item.v9_jd_intelligence?.employer_identity_labels || []);

const baseline = stableFields(item.v9_safe_baseline_fields || {});
let fields = stableFields(
  item.v9_authoritative_resume_fields ||
  item.authoritative_resume_fields ||
  item.final_resume_fields ||
  item.resume_fields ||
  item.template_fields ||
  baseline
);

const ledger = Array.isArray(item.v9_jd_intelligence?.weighted_term_ledger)
  ? item.v9_jd_intelligence.weighted_term_ledger
  : [];
const supported = ledger.filter(row => row.supported === true);
const allowedNumbers = new Set(unique(item.v9_resume_evidence?.approved_numeric_tokens || []));
const evidenceItems = Array.isArray(item.v9_resume_evidence?.evidence_items)
  ? item.v9_resume_evidence.evidence_items
  : [];
const evidenceText = norm(evidenceItems.map(entry => `${entry.text || ""} ${(entry.keywords || []).join(" ")}`).join(" "));

const revertedForTruth = [];

// 1. Numeric truth audit: only strict verified numeric result tokens are allowed in mutable narratives.
for (const key of NARRATIVE_FIELDS) {
  const bad = numericTokens(fields[key]).filter(token => !allowedNumbers.has(token));
  if (bad.length) {
    fields[key] = baseline[key];
    revertedForTruth.push({ key, reason: "unverified_number", tokens: bad });
  }
}

// 2. Block unsupported named tools anywhere in mutable content.
const unsupportedNamedTools = (item.v9_jd_intelligence?.unsupported_terms || [])
  .filter(row => row.named_tool === true)
  .map(row => clean(row.canonical || row.exact_jd_phrase))
  .filter(Boolean);

for (const key of [...NARRATIVE_FIELDS, ...SKILL_FIELDS]) {
  const hits = unsupportedNamedTools.filter(tool => norm(fields[key]).includes(norm(tool)) && !evidenceText.includes(norm(tool)));
  if (hits.length) {
    fields[key] = baseline[key];
    revertedForTruth.push({ key, reason: "unsupported_named_tool", tools: hits });
  }
}

// 2b. Semantic truth: familiarity/exposure must not become proficiency/experience.
for (const key of NARRATIVE_FIELDS) {
  const tool = exposureOverclaim(fields[key], exposureOnlyTools);
  if (tool) {
    fields[key] = baseline[key];
    revertedForTruth.push({ key, reason: "systems_exposure_overclaim", tool });
  }
}

// 2c. Semantic identity: employer target titles are not candidate titles.
const adoptedIdentity = summaryIdentityOverclaim(fields.SUMMARY, employerIdentityLabels);
if (adoptedIdentity) {
  fields.SUMMARY = baseline.SUMMARY;
  revertedForTruth.push({ key: "SUMMARY", reason: "employer_title_identity_overclaim", label: adoptedIdentity });
}

// 3. Restore any narrative that violates the production field-length contract.
for (const key of NARRATIVE_FIELDS) {
  if (!fieldLengthOK(key, fields[key])) {
    fields[key] = baseline[key];
    revertedForTruth.push({ key, reason: "field_length_contract" });
  }
}

// 4. Avoid near-duplicate bullets by restoring the later field to its safe baseline.
const bulletKeys = CANONICAL_FIELDS.filter(key => key.includes("BULLET"));
for (let i = 0; i < bulletKeys.length; i += 1) {
  for (let j = i + 1; j < bulletKeys.length; j += 1) {
    const a = bulletKeys[i];
    const b = bulletKeys[j];
    if (fields[a] && fields[b] && nearDuplicate(fields[a], fields[b])) {
      fields[b] = baseline[b];
      revertedForTruth.push({ key: b, reason: `near_duplicate_of:${a}` });
    }
  }
}

// 5. Aggressive but truthful exact-JD rescue.
// Only evidence-supported terms are eligible, and skills are the safest placement surface.
// If the page-density ceiling is tight, first remove generic skill terms that the JD does not request.
// This is preferable to dropping a high-weight, truth-supported employer phrase.
const jdText = norm(item.v9_jd_intelligence?.full_job_description || "");
const skillMinimumChars = {
  DATA_ANALYTICS_SKILLS: 95,
  HR_OPERATIONS_SKILLS: 100,
  COMPLIANCE_TOOLS: 80
};
const prunedGenericSkills = [];

function makeRoomFor(candidatePhrase, targetField) {
  const order = [
    "DATA_ANALYTICS_SKILLS",
    "COMPLIANCE_TOOLS",
    "HR_OPERATIONS_SKILLS"
  ];

  const testWithPhrase = () => {
    const nextTerms = unique([candidatePhrase, ...splitSkills(fields[targetField])]);
    return { ...fields, [targetField]: nextTerms.join(" | ") };
  };

  if (totalChars(testWithPhrase()) <= 3660) return true;

  for (const key of order) {
    let terms = splitSkills(fields[key]);

    // Lowest-value candidates first: not asked for by this JD and not themselves exact supported JD phrases.
    for (let i = terms.length - 1; i >= 0; i -= 1) {
      const term = terms[i];
      const askedFor = jdText.includes(norm(term));
      const exactSupported = supported.some(row =>
        norm(row.exact_jd_phrase || row.canonical) === norm(term)
      );

      if (askedFor || exactSupported) continue;

      const trialTerms = terms.filter((_, index) => index !== i);
      const trialValue = trialTerms.join(" | ");
      if (trialValue.length < Number(skillMinimumChars[key] || 70)) continue;

      terms = trialTerms;
      fields[key] = trialValue;
      prunedGenericSkills.push({ field: key, term });

      if (totalChars(testWithPhrase()) <= 3660) return true;
    }
  }

  return totalChars(testWithPhrase()) <= 3660;
}

const insertedTerms = [];
const sortedSupported = [...supported].sort((a, b) => Number(b.weight || 0) - Number(a.weight || 0));

for (const row of sortedSupported) {
  if (weightedCoverage(supported, fields) >= 95) break;

  const phrase = clean(row.exact_jd_phrase || row.canonical);
  if (!phrase) continue;

  const currentResume = norm(CANONICAL_FIELDS.map(key => fields[key]).join(" "));
  if (currentResume.includes(norm(phrase))) continue;

  const evidenceIds = Array.isArray(row.evidence_ids) ? row.evidence_ids : [];
  if (!evidenceIds.length) continue;

  const key = fieldForRow(row);

  // Make room by pruning generic non-JD skills before giving up on a high-value exact phrase.
  if (!makeRoomFor(phrase, key)) continue;

  const terms = splitSkills(fields[key]);
  const next = unique([phrase, ...terms]);
