    .replace(/[\u2018\u2019]/g, "'")
    .replace(/[\u201c\u201d]/g, '"')
    .replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/g, " ")
    .replace(/[\u200B-\u200D\u2060\uFEFF]/g, "")
    .replace(/\s+/g, " ")
    .replace(/\s+([,.;:!?])/g, "$1")
    .trim();
}

function norm(value) {
  return clean(value)
    .toLowerCase()
    .replace(/[^a-z0-9+#.%/-]+/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

function isObject(value) {
  return Boolean(value && typeof value === "object" && !Array.isArray(value));
}

function clone(value) {
  return JSON.parse(JSON.stringify(value ?? {}));
}

function unique(values) {
  const seen = new Set();
  const out = [];
  for (const raw of values || []) {
    const value = clean(raw);
    const key = norm(value);
    if (value && key && !seen.has(key)) {
      seen.add(key);
      out.push(value);
    }
  }
  return out;
}

function stableFields(source) {
  const out = {};
  for (const key of CANONICAL_FIELDS) out[key] = clean(source?.[key]);
  return out;
}

function totalChars(fields) {
  return CANONICAL_FIELDS.reduce((sum, key) => sum + clean(fields?.[key]).length, 0);
}

function hashFields(fields) {
  const input = JSON.stringify(stableFields(fields));
  let hash = 0x811c9dc5;
  for (let i = 0; i < input.length; i += 1) {
    hash ^= input.charCodeAt(i);
    hash = Math.imul(hash, 0x01000193) >>> 0;
  }
  return `fnv1a32:${hash.toString(16).padStart(8, "0")}:${input.length}`;
}

function numericTokens(text) {
  return unique(clean(text).match(/\d[\d,]*(?:\.\d+)?(?:%|\+)?/g) || []);
}

function splitList(value) {
  return unique(clean(value).split(/\s*(?:\||,|;)\s*/).filter(Boolean));
}

function cleanList(value, key) {
  const values = splitList(value);
  if (key === "COURSEWORK") {
    return `Coursework: ${values.map(v => v.replace(/^coursework\s*:\s*/i, "")).filter(Boolean).join(", ")}`;
  }
  return values.join(" | ");
}

function fieldLengthOK(key, value) {
  const len = clean(value).length;
  if (key === "SUMMARY") return len >= 300 && len <= 345;
  if (/^COMPANY_[12]_BULLET_/.test(key)) return len >= 115 && len <= 190;
  if (/^PROJECT_[12]_BULLET_/.test(key)) return len >= 100 && len <= 190;
  if (key === "COURSEWORK") return len >= 60 && len <= 280;
  if (SKILL_FIELDS.has(key)) return len >= 70 && len <= 430;
  return len > 0;
}

function extractCandidate(root) {
  const queue = [root];
  const seen = new Set();

  while (queue.length) {
    let value = queue.shift();
    if (value === null || value === undefined) continue;

    if (typeof value === "string") {
      let text = value
        .replace(/^```(?:json)?\s*/i, "")
        .replace(/\s*```$/i, "")
        .trim();
      try {
        value = JSON.parse(text);
      } catch (_) {
        const first = text.indexOf("{");
        const last = text.lastIndexOf("}");
        if (first >= 0 && last > first) {
          try { value = JSON.parse(text.slice(first, last + 1)); }
          catch (_) { continue; }
        } else continue;
      }
    }

    if (!value || typeof value !== "object" || seen.has(value)) continue;
    seen.add(value);

    const directFields = value.final_fields || value.resume_fields || value.improved_fields;
    if (isObject(directFields)) {
      return {
        root: value,
        fields: directFields,
        field_evidence: value.field_evidence || value.evidence_ids || {},
        jd_analysis: value.jd_analysis || value.analysis || {},
        notes: value.notes || value.validation_notes || []
      };
    }

    if (isObject(value.output)) {
      const nestedFields = value.output.final_fields || value.output.resume_fields || value.output.improved_fields;
      if (isObject(nestedFields)) {
        return {
          root: value.output,
          fields: nestedFields,
          field_evidence: value.output.field_evidence || value.output.evidence_ids || {},
          jd_analysis: value.output.jd_analysis || value.output.analysis || {},
          notes: value.output.notes || []
        };
      }
    }

    for (const child of Object.values(value)) queue.push(child);
  }

  return null;
}

function nearDuplicate(a, b) {
  const A = new Set(norm(a).split(" ").filter(word => word.length > 3));
  const B = new Set(norm(b).split(" ").filter(word => word.length > 3));
  if (!A.size || !B.size) return false;
  let common = 0;
  for (const word of A) if (B.has(word)) common += 1;
  const ratio = common / Math.min(A.size, B.size);
  return ratio >= 0.78;
}

function buildMarkdown(fields) {
  const line = value => clean(value);
  const bullet = value => clean(value) ? `- ${clean(value)}` : "";
  const blocks = [
