      line(fields.DATA_ANALYTICS_SKILLS) ? `Data & Analytics: ${line(fields.DATA_ANALYTICS_SKILLS)}` : "",
      line(fields.HR_OPERATIONS_SKILLS) ? `HR Operations: ${line(fields.HR_OPERATIONS_SKILLS)}` : "",
      line(fields.COMPLIANCE_TOOLS) ? `Compliance & Tools: ${line(fields.COMPLIANCE_TOOLS)}` : ""
    ].filter(Boolean).join("\n"),
    [
      "CERTIFICATIONS & SIMULATIONS",
      bullet(fields.CERT_1), bullet(fields.CERT_2), bullet(fields.CERT_3), bullet(fields.CERT_4), bullet(fields.CERT_5)
    ].filter(Boolean).join("\n"),
    [
      "HR AND ANALYTICS PROJECTS",
      line(fields.PROJECT_1_NAME), line(fields.PROJECT_1_TOOLS) ? `Tools: ${line(fields.PROJECT_1_TOOLS)}` : "",
      bullet(fields.PROJECT_1_BULLET_1), bullet(fields.PROJECT_1_BULLET_2),
      line(fields.PROJECT_2_NAME), line(fields.PROJECT_2_TOOLS) ? `Tools: ${line(fields.PROJECT_2_TOOLS)}` : "",
      bullet(fields.PROJECT_2_BULLET_1), bullet(fields.PROJECT_2_BULLET_2)
    ].filter(Boolean).join("\n"),
    [
      "WORK EXPERIENCE",
      [fields.COMPANY_1, fields.DATE_1].map(line).filter(Boolean).join(" | "), line(fields.ROLE_1),
      bullet(fields.COMPANY_1_BULLET_1), bullet(fields.COMPANY_1_BULLET_2), bullet(fields.COMPANY_1_BULLET_3), bullet(fields.COMPANY_1_BULLET_4),
      [fields.COMPANY_2, fields.DATE_2].map(line).filter(Boolean).join(" | "), line(fields.ROLE_2),
      bullet(fields.COMPANY_2_BULLET_1), bullet(fields.COMPANY_2_BULLET_2), bullet(fields.COMPANY_2_BULLET_3)
    ].filter(Boolean).join("\n")
  ];
  return blocks.filter(Boolean).join("\n\n");
}

function syncAliases(target, fields) {
  const exact = stableFields(fields);
  for (const alias of [
    "v9_authoritative_resume_fields", "authoritative_resume_fields", "final_resume_fields",
    "resume_fields", "resume_template_fields", "template_fields", "placeholder_values",
    "doc_fields", "google_doc_fields", "replacements", "fields"
  ]) target[alias] = clone(exact);

  target.authoritative_resume_hash = hashFields(exact);
  target.authoritative_resume_field_chars = totalChars(exact);
  target.authoritative_resume_field_count = CANONICAL_FIELDS.length;
  target.authoritative_resume_populated_field_count = CANONICAL_FIELDS.filter(key => clean(exact[key])).length;
  return exact;
}

function exposureOnlyToolsFromIntel(source) {
