    .filter(row => row?.named_tool === true && (row?.support_mode === "exposure" || row?.support_level === "familiarity" || row?.allowed_claim_style === "familiarity_only"))
    .map(row => clean(row.canonical || row.exact_jd_phrase)));
}

function hasExposureOverclaim(value, tools) {
  const text = clean(value);
  for (const tool of tools) {
    if (!norm(text).includes(norm(tool))) continue;
    const safe = new RegExp(`(?:familiarity|familiar|exposure|concepts?)\\s+(?:with|to)?\\s*${tool.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}|${tool.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}\\s+(?:familiarity|concepts?|exposure)`, "i");
    if (safe.test(text)) continue;
    const overclaim = /\b(?:proficient|proficiency|skilled|experienced|experience|hands-on|advanced|expert|implemented|configured|administered|owned|managed|used|using)\b/i.test(text);
    if (overclaim) return tool;
  }
  return "";
}

function qualifyExposureToolsInSkillList(value, tools) {
  let output = clean(value);
  for (const tool of tools) {
    const escaped = tool.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
    const alreadyQualified = new RegExp(`${escaped}\\s+(?:Familiarity|Concepts?|Exposure)|(?:Familiarity|Exposure)\\s+(?:with\\s+)?${escaped}`, "i");
    if (alreadyQualified.test(output)) continue;
    output = output.replace(new RegExp(`\\b${escaped}\\b`, "gi"), `${tool} Familiarity`);
  }
  return clean(output);
}

function summaryAdoptsEmployerIdentity(value, labels) {
  const text = norm(value);
  return labels.find(label => {
    const n = norm(label);
    return n && (text.startsWith(`${n} `) || text === n);
  }) || "";
}

