  // Do not destroy a stronger tailored resume merely because it is shorter than the fullness target.
  // Prefer longer truth-safe baseline values only when they actually add useful depth and stay under HARD_MAX.
  const fillPriority = [
    "SUMMARY",
    "COMPANY_1_BULLET_1",
    "COMPANY_1_BULLET_2",
    "COMPANY_1_BULLET_3",
    "COMPANY_1_BULLET_4",
    "COMPANY_2_BULLET_1",
    "COMPANY_2_BULLET_2",
    "COMPANY_2_BULLET_3",
    "PROJECT_1_BULLET_1",
    "PROJECT_1_BULLET_2",
    "PROJECT_2_BULLET_1",
    "PROJECT_2_BULLET_2",
    "HR_OPERATIONS_SKILLS",
    "DATA_ANALYTICS_SKILLS",
    "COMPLIANCE_TOOLS",
    "COURSEWORK"
  ];

