  Array.isArray(item.v9_resume_evidence?.approved_numeric_tokens)
    ? item.v9_resume_evidence.approved_numeric_tokens.map(clean)
    : []
);
const finalUnverifiedNumbers = strictNarrativeKeys.flatMap(key =>
  numericTokens(fields[key])
    .filter(token => !allowedNumbers.has(token))
    .map(token => ({ key, token }))
);

const evidenceText = clean(
  (item.v9_resume_evidence?.evidence_items || [])
    .map(entry => `${entry.text || ""} ${(entry.keywords || []).join(" ")}`)
    .join(" ")
).toLowerCase();
const unsupportedNamedTools = (item.v9_jd_intelligence?.unsupported_terms || [])
  .filter(row => row.named_tool === true)
  .map(row => clean(row.canonical || row.exact_jd_phrase))
  .filter(Boolean);
const finalMutableText = clean([
  ...strictNarrativeKeys.map(key => fields[key]),
  fields.DATA_ANALYTICS_SKILLS,
  fields.HR_OPERATIONS_SKILLS,
  fields.COMPLIANCE_TOOLS
].join(" ")).toLowerCase();
const finalUnsupportedTools = unsupportedNamedTools.filter(tool =>
  finalMutableText.includes(clean(tool).toLowerCase()) &&
  !evidenceText.includes(clean(tool).toLowerCase())
);

const currentHash = hashFields(fields);
const audit = item.v9_exact_jd_audit || {};
const hrAgentScore = Number(
  item.hr_agent_result?.overall_score ??
  item.tailored_resumes?.[0]?.final_hr_agent_score_after_improvement ??
  item.sheet_rows?.Tailored_Resumes?.[0]?.final_hr_agent_score_after_improvement ??
  0
);
const callCount = Number(item.v9_openai_call_count || 0);
const maxCalls = Number(item.v9_single_call_policy?.max_paid_openai_calls_per_job || 1);

const checks = {
  v9_jd_intelligence_present: item.v9_jd_intelligence?.version === "V9.2",
  complete_job_description_present: item.v9_jd_intelligence?.jd_present === true && clean(item.v9_jd_intelligence?.full_job_description).length >= 120,
  exact_jd_coverage_95_plus: Number(audit.weighted_exact_jd_coverage || 0) >= 95,
  final_hr_agent_score_95_plus: Number.isFinite(hrAgentScore) && hrAgentScore >= 95,
  v9_truth_passed: audit.truth_passed === true && item.v9_truth_audit_passed === true,
  final_strict_numeric_integrity: finalUnverifiedNumbers.length === 0,
  final_unsupported_named_tools_zero: finalUnsupportedTools.length === 0,
  critical_terms_complete: Array.isArray(audit.critical_terms_missing) && audit.critical_terms_missing.length === 0,
  paid_openai_call_budget: callCount <= maxCalls,
  authoritative_hash_matches_fields:
    !item.authoritative_resume_hash || item.authoritative_resume_hash === currentHash,
  existing_final_gate_not_bypassed:
    item.final_gate_checks_v5 && typeof item.final_gate_checks_v5 === "object"
};

const failed = Object.entries(checks)
  .filter(([, passed]) => !passed)
  .map(([name]) => name);

const truthOrIntegrityFailure =
  !checks.v9_truth_passed ||
  !checks.final_strict_numeric_integrity ||
  !checks.final_unsupported_named_tools_zero ||
  !checks.paid_openai_call_budget ||
  !checks.authoritative_hash_matches_fields;

if (failed.length > 0) {
  // Never upgrade anything. Lower only the strict-ready flags.
  item.writer_preflight_ready = false;
  item.preflight_ready = false;
  item.final_resume_ready = false;
  item.application_ready = false;
  item.final_gate_status = "v9_contract_review_required";

  // Coverage-only failures may still render a review copy if the existing final gate allowed it.
  // Truth / call-budget / hash-integrity failures block even the best-effort writer.
  if (truthOrIntegrityFailure) {
    item.best_effort_writer_allowed = false;
    item.best_effort_review_allowed = false;
    item.resume_document_mode = "blocked_v9_truth_or_integrity";
  } else if (item.best_effort_review_allowed === true) {
    item.resume_document_mode = "review_only_v9_coverage";
  }
}

item.v9_post_guard_contract = {
  version: "V9.2",
  passed: failed.length === 0,
  checks,
  failed_checks: failed,
  paid_openai_call_count: callCount,
  max_paid_openai_calls: maxCalls,
  final_hr_agent_score: hrAgentScore,
  authoritative_resume_hash: item.authoritative_resume_hash || "",
  calculated_authoritative_hash: currentHash,
  existing_final_gate_status_before_v9_contract:
    item.final_gate_content_quality_v5?.strict_preflight === true
      ? "strict_preflight_pass"
      : "not_strict_preflight_pass",
  final_unverified_numeric_tokens: finalUnverifiedNumbers,
  final_unsupported_named_tools: finalUnsupportedTools,
  physical_pdf_page_count_still_required: true
};

item.logs.push({
  run_id: item.run_id || "",
  timestamp: new Date().toISOString(),
  node_name: "V9 Post-Guard Contract Check",
  status: failed.length === 0 ? "success" : "warning",
  message:
    failed.length === 0
      ? "V9.2 contract passed after the existing production final gate; rendered PDF verification is still required."
      : `V9.2 contract lowered readiness because: ${failed.join(", ")}.`,
  cost_control_note:
    "This node can only lower readiness; it cannot override or upgrade the existing Final 95+ Gate. Telegram/TG untouched.",
  error_detail: failed.length === 0 ? "" : JSON.stringify({ failed })
});

return [{ json: item }];
